class Solution {
public:
    vector<int> numberOfPairs(
        vector<int>& nums1,
        vector<int>& nums2,
        vector<vector<int>>& queries) {

        int n = nums2.size();
        int B = 320;
        int blocks = (n + B - 1) / B;

        vector<long long> a(nums2.begin(), nums2.end());
        vector<long long> lazy(blocks, 0);

        vector<unordered_map<long long, int>> freq(blocks);

        // Build frequency maps for every block.
        for (int i = 0; i < n; ++i) {
            freq[i / B][a[i]]++;
        }

        auto updatePartial = [&](int b, int l,
                                 int r, long long val) {
            for (int i = l; i <= r; ++i) {
                long long oldValue = a[i];
                long long newValue = oldValue + val;

                auto it = freq[b].find(oldValue);

                if (--it->second == 0)
                    freq[b].erase(it);

                freq[b][newValue]++;
                a[i] = newValue;
            }
        };

        vector<int> answer;
        answer.reserve(queries.size());

        for (const auto& q : queries) {

            if (q[0] == 1) {
                int l = q[1];
                int r = q[2];
                long long val = q[3];

                int leftBlock = l / B;
                int rightBlock = r / B;

                if (leftBlock == rightBlock) {
                    updatePartial(leftBlock, l, r, val);
                } else {
                    int leftEnd =
                        min(n - 1, (leftBlock + 1) * B - 1);

                    updatePartial(leftBlock, l, leftEnd, val);

                    for (int b = leftBlock + 1;
                         b < rightBlock; ++b) {
                        lazy[b] += val;
                    }

                    int rightStart = rightBlock * B;
                    updatePartial(rightBlock, rightStart, r, val);
                }

            } else {
                long long target = q[1];
                int count = 0;

                for (int x : nums1) {
                    long long needed = target - x;

                    for (int b = 0; b < blocks; ++b) {
                        long long key = needed - lazy[b];

                        auto it = freq[b].find(key);

                        if (it != freq[b].end())
                            count += it->second;
                    }
                }

                answer.push_back(count);
            }
        }

        return answer;
    }
};
